async () => { const g=document.querySelector('vaadin-grid'); const sleep=ms=>new Promise(r=>setTimeout(r,ms)); const done=[]; 
const findRow=()=>{ for(const tr of g.shadowRoot.querySelectorAll('tbody tr')){ const t=[...tr.querySelectorAll('slot')].map(s=>s.assignedNodes()[0]); if(t[4] && t[3].textContent.trim()==='Closed (lost)' && t[4].textContent.trim()==='Avaya Inc.') return t; } return null; };
for(let round=0; round<20; round++){ let t=null; const n=g.size; for(let i=0;i<n+12 && !t;i+=12){ g.scrollToIndex(Math.min(i,n-1)); await sleep(120); t=findRow(); } if(!t) break; const email=t[2].textContent.trim(); t[2].click(); await sleep(400); const inputs=[...document.querySelectorAll('vaadin-text-field,vaadin-email-field')]; const vals=inputs.map(i=>i.value); if(!vals.includes(email)) {return {err:'form mismatch',email,vals,done};} const btn=[...document.querySelectorAll('vaadin-button')].find(b=>b.textContent.trim()==='Delete'); btn.click(); await sleep(600); done.push(email); }
return {done}; }

